function formatPrice(cents) {
  return "$" + cents / 100;
}

function discountPrice(cents, percent) {
  return cents * percent / 100;
}
module.exports = { formatPrice, discountPrice };

function add(a, b) {
  return a + b;
}

/**
 * Returns n constrained to the inclusive range [min, max].
 * @param {number} n - value to clamp
 * @param {number} min - lower bound
 * @param {number} max - upper bound
 * @returns {number} min if n < min, max if n > max, otherwise n
 */
function clamp(n, min, max) {
  return Math.min(max, Math.max(min, n));
}

module.exports = { add, clamp };

const test = require("node:test");
const assert = require("node:assert");
const { add, clamp } = require("./calc.js");

test("add returns the sum", () => {
  assert.equal(add(2, 3), 5);
});

test("clamp leaves an in-range value unchanged", () => {
  assert.equal(clamp(5, 0, 10), 5);
});

test("clamp raises a value below min up to min", () => {
  assert.equal(clamp(-3, 0, 10), 0);
});

test("clamp lowers a value above max down to max", () => {
  assert.equal(clamp(42, 0, 10), 10);
});

