const conv = (cents, from, to, R, M) => {
  const minor = c => M[c] || 100;
  return Math.round((cents / minor(from)) * (R[to] / R[from]) * minor(to));
};
const R = { USD: 1, EUR: 0.9, GBP: 0.8, JPY: 150 };
const M = { JPY: 1 };
const cases = [
  [100, "USD", "EUR", 90], [100, "USD", "GBP", 80], [100, "USD", "JPY", 150],
  [150, "JPY", "USD", 100], [125, "USD", "GBP", 100], [1999, "USD", "EUR", 1799],
  [1, "JPY", "USD", 1], [149, "JPY", "USD", 99], [-100, "USD", "EUR", -90],
  [-1, "JPY", "USD", -1], [0, "USD", "EUR", 0],
  [3, "USD", "XYZ", 2, { USD: 1, XYZ: 0.5 }],
];
for (const [c, f, t, exp, rt] of cases) {
  const got = conv(c, f, t, rt || R, M);
  console.log(`${c} ${f}->${t} = ${got} (expect ${exp}) ${got === exp ? "OK" : "MISMATCH"}`);
}
// raw (unrounded) values for the tricky ones:
console.log("raw 1999 USD->EUR:", (1999/100)*(0.9/1)*100);
console.log("raw 150 JPY->JPY (no shortcut):", (150/1)*(150/150)*1);
console.log("raw 100 USD->EUR:", (100/100)*(0.9/1)*100);
console.log("Math.round(-0.5)=", Math.round(-0.5), " Math.round(1.5)=", Math.round(1.5));
'

