let input=0, output=0, reasoning=0;
for (const e of lines) {
  const u = e.type === "message" && e.message && e.message.role === "assistant" ? e.message.usage : null;
  if (u) { input += u.input||0; output += u.output||0; reasoning += u.reasoning||0; }
}
console.log(JSON.stringify({input, output, reasoning, entries: lines.length}));
'

